// Grade Average in textbook style: the project writes using namespace std;, so the code says cout and min, but ::count and ::max where std has the same names.
int main() {
    vector<int> grades{};
    cout << "Enter grades from 0 to 100, and -1 to finish." << '\n';
    while (true) {
        int grade = 0;
        grade = b2c::ask<int>("Grade: ");
        if (grade == -1) {
            break;
        }
        if (grade < 0 || grade > 100) {
            cout << "A grade must be from 0 to 100." << '\n';
            continue;
        }
        grades.push_back(grade);
        ++::count;
    }
    cout << "" << '\n';
    if (::count == 0) {
        cout << "No grades." << '\n';
        return 0;
    }
    cout << "Grades:";
    int total = 0;
    int highest = grades.at(0);
    int lowest = grades.at(0);
    for (const auto& grade : grades) {
        cout << " " << grade;
        total += grade;
        highest = ::max(highest, grade);
        lowest = min<int>(lowest, grade);
    }
    cout << "" << '\n';
    double average = static_cast<double>(total) / static_cast<double>(::count);
    double curved = std::max<double>(average, 80.0);
    int above = 0;
    for (const auto& grade : grades) {
        if (grade > average) {
            ++above;
        }
    }
    cout << fixed << setprecision(2);
    cout << "Count: " << ::count << '\n';
    cout << "Average: " << average << '\n';
    cout << "Highest: " << highest << '\n';
    cout << "Lowest: " << lowest << '\n';
    cout << "Above the average: " << above << '\n';
    cout << "Curved average: " << curved << '\n';
    return 0;
}
